import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Piramide retta","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/g_geometria-dello-spazio/gj/gjc.md","filePath":"lezioni/g_geometria-dello-spazio/gj/gjc.md"}`),a={name:`lezioni/g_geometria-dello-spazio/gj/gjc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="piramide-retta" tabindex="-1">Piramide retta <a class="header-anchor" href="#piramide-retta" aria-label="Permalink to “Piramide retta”">​</a></h1><blockquote><p>Per poter avere esercizi abbastanza semplici, senza dover fare un calcolo per ogni faccia della piramide abbiamo bisogno di pensare a piramidi che abbiano le facce uguali, o almeno con le stesse altezze; diventa quindi essenziale pensare a piramidi che abbiano delle particolari caratteristiche.</p><p>Intendiamoci: nulla vieta di fare esercizi con piramidi oblique e mi ricordo che in un tema d&#39;esame della maturità magistrale si dovevano calcolare tutti gli spigoli e le altezze delle varie facce diverse fra loro, ma nella mia carriera gli esercizi che ho visto di questo tipo si contano sulle dita di una mano.</p></blockquote><p>Consideriamo l&#39;insieme dei poligoni circoscritti ad una circonferenza: se la nostra piramide ha come base uno di tali poligoni e la perpendicolare dal vertice cade esattamente nel centro del cerchio inscritto nel poligono allora diremo che tale piramide è <strong>retta</strong>.</p><p>Come esempio in figura hai una piramide triangolare retta (un triangolo è sempre circoscrivibile ad un cerchio).</p><p>Da notare che, essendo congruenti i raggi <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>H</mi><mi>D</mi></mrow><annotation encoding="application/x-tex">HD</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>H</mi><mi>E</mi></mrow><annotation encoding="application/x-tex">HE</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>H</mi><mi>F</mi></mrow><annotation encoding="application/x-tex">HF</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span></span></span></span> ed essendo comune il segmento <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>V</mi><mi>H</mi></mrow><annotation encoding="application/x-tex">VH</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span>, avremo che i tre triangoli <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>V</mi><mi>H</mi><mi>D</mi></mrow><annotation encoding="application/x-tex">VHD</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord mathnormal" style="margin-right:0.0278em;">D</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>V</mi><mi>H</mi><mi>E</mi></mrow><annotation encoding="application/x-tex">VHE</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>V</mi><mi>H</mi><mi>F</mi></mrow><annotation encoding="application/x-tex">VHF</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span></span></span></span> sono congruenti, cioè le apoteme di una piramide retta sono sempre congruenti fra loro.</p><blockquote><p><strong>Nota:</strong> In figura, per non appesantire, ho disegnato completo solo il triangolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>V</mi><mi>H</mi><mi>F</mi></mrow><annotation encoding="application/x-tex">VHF</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span></span></span></span>.</p></blockquote><p>Diremo infine <strong>regolare</strong> una piramide retta che abbia come base un poligono regolare.</p><p>In tal caso tutte le facce laterali della piramide sono tra loro congruenti.</p><p>A destra una piramide esagonale regolare.</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};